		/** 
		 * Tests creating a new Employee.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Employee");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Employee" );

			try {            
				Employee entity = EmployeeService.getEmployeeInstance().createEmployee( generateNewEntity() );
				thePrimaryKey = entity.getEmployeeId();
				LOGGER.info( "-- Successfully created a Employee with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Employee. 
		 */
		public Employee testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Employee" );

			Employee entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Employee with primary key" );
			msg.append( thePrimaryKey );
			
			EmployeeFetchOneSummary fetchOneSummary = new EmployeeFetchOneSummary( thePrimaryKey );

			try {
				entity = EmployeeService.getEmployeeInstance().getEmployee( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Employee " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Employee.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Employee." );

			StringBuilder msg = new StringBuilder( "Failed to update a Employee : " );        
			Employee entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Employee." );

				// for use later on...
				thePrimaryKey = entity.getEmployeeId();

				EmployeeService proxy = EmployeeService.getEmployeeInstance();            
				proxy.updateEmployee( entity );   

				LOGGER.info( "-- Successfully saved Employee - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Employee.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Employee." );

			try{
			    Employee entity = testRead(); 
				EmployeeService.getEmployeeInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Employee with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Employee with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Employees.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Employees:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Employee : " );        
			List<Employee> collection  = null;

			try {
				// call the static get method on the EmployeeService
				collection = EmployeeService.getEmployeeInstance().getAllEmployee();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Employee entity = null;            
					Iterator<Employee> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getEmployeeId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

